import { useState } from 'react';
import { Cliente, ClienteMock } from "@/app/mock/cliente"
import { useDraft } from '@/app/context/DraftContext';

interface RascunhoAlertaProps {
    setClientes: React.Dispatch<React.SetStateAction<Cliente>>;
}

export const Alert = ({ setClientes }: RascunhoAlertaProps) => {
    const { draft, temRascunho, limparRascunho } = useDraft();
    const [visivel, setVisivel] = useState(true);

    // Se não tiver rascunho ou o alerta já foi fechado, não renderiza nada
    if (!temRascunho || !visivel) return null;

    const handleContinuar = () => {
        if (draft) {
            setClientes(prev => new Cliente(
                prev.id,
                draft.nome || prev.nome,
                draft.telefone || prev.telefone,
                draft.cpf || prev.cpf,
                prev.status
            ));
        }
        setVisivel(false);
    };

    const handleNovo = () => {
        limparRascunho();
        setVisivel(false);
    };

    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
            <div className="bg-white dark:bg-[#2B344B] p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full border border-white/10">
                <h3 className="text-xl font-black text-slate-900 dark:text-slate-50 uppercase italic tracking-tighter">
                    Cadastro <span className="text-amber-500">Incompleto</span>
                </h3>
                <p className="text-sm text-slate-500 dark:text-slate-400 mt-4 leading-relaxed">
                    Notamos que você começou um cadastro recentemente. Deseja recuperar os dados ou prefere iniciar um novo registro do zero?
                </p>
                
                <div className="flex flex-col sm:flex-row gap-3 mt-8">
                    <button 
                        onClick={handleNovo}
                        className="flex-1 px-4 py-4 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-red-500 transition-colors order-2 sm:order-1"
                    >
                        Descartar
                    </button>
                    <button 
                        onClick={handleContinuar}
                        className="flex-1 px-8 py-4 bg-amber-500 text-[#2B344B] font-black rounded-2xl text-[10px] uppercase tracking-[0.2em] hover:bg-amber-400 transition-all shadow-lg shadow-amber-500/20 active:scale-95 order-1 sm:order-2"
                    >
                        Continuar
                    </button>
                </div>
            </div>
        </div>
    );
};